"""A process-wide plugin hub."""

_plugins = []
_seq = 0
_runs = 0
_errors = []


def reset():
    global _seq, _runs
    del _plugins[:]
    del _errors[:]
    _seq = 0
    _runs = 0


def register(name, fn, priority=0):
    global _seq
    if not isinstance(name, str) or not name:
        raise ValueError("plugin name must be a non-empty string")
    if any(p[0] == name for p in _plugins):
        raise ValueError("duplicate plugin: " + name)
    _seq += 1
    _plugins.append((name, fn, priority, _seq))


def unregister(name):
    for i, p in enumerate(_plugins):
        if p[0] == name:
            del _plugins[i]
            return
    raise KeyError(name)


def _ordered():
    return sorted(_plugins, key=lambda p: (-p[2], p[3]))


def names():
    return [p[0] for p in _ordered()]


def run(event):
    global _runs
    _runs += 1
    del _errors[:]
    results = []
    for name, fn, _priority, _order in _ordered():
        try:
            results.append(fn(event))
        except Exception:
            _errors.append(name)
    return results


def last_errors():
    return list(_errors)


def runs():
    return _runs

